  /** Queries all chain items. */
  ChainAll(request: QueryChainAllRequest): Promise<QueryChainAllResponse>;
  /** Queries a list of PoolBalance items. */
  PoolBalance(request: QueryPoolBalanceRequest): Promise<QueryPoolBalanceResponse>;
  /** Queries a list of all PoolBalance items. */
  PoolBalanceAll(request: QueryPoolBalanceAllRequest): Promise<QueryPoolBalanceAllResponse>;
